// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzz the calldata selector and a switch that decides whether the callee should revert.
    // The important adversarial behavior (a callee that can be made to revert) is provided
    // by the Reverter helper deployed below. We fuzz a bytes value so the fuzzer can
    // choose any calldata; the helper ignores calldata and simply reverts when asked.
    function testFuzz_property(bytes memory data, bool shouldRevert) public {
        // Deploy a helper that will either revert or accept the call based on shouldRevert
        Reverter r = new Reverter();

        // Make the helper toggle its behavior according to the fuzzed boolean.
        r.setShouldRevert(shouldRevert);

        // Call c.forward and observe whether it reverted. The correct contract MUST revert
        // when the low-level call to a reverting callee fails; the mutant (which drops the
        // require) will not revert when shouldRevert == true.
        bool ok;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (assertion): ok == (!shouldRevert)
        // - If the callee is set to revert (shouldRevert == true), the reference contract's
        //   forward must revert (ok == false). The mutant that ignores the success flag
        //   will produce ok == true for that input, causing this assertion to fail on the mutant.
        // - If the callee does not revert, both should succeed (ok == true).
        assertTrue(ok == (!shouldRevert));
    }
}

// Adversarial helper: can be toggled to revert or accept. Has a payable fallback so any
// low-level call (with arbitrary calldata/value) reaches it. The test deploys this helper
// and controls its behavior via setShouldRevert.
contract Reverter {
    bool public shouldRevert;
    function setShouldRevert(bool v) public { shouldRevert = v; }
    fallback() external payable {
        if (shouldRevert) revert("revert on demand");
    }
    receive() external payable {
        if (shouldRevert) revert("revert on demand");
    }
}
